import React, { Component } from 'react';
import {
    CButton, CCard, CCardBody, CCardGroup, CCol, CContainer, CForm, CInput,
    CInputGroup, CInputGroupPrepend, CInputGroupText, CRow
} from '@coreui/react';
import CIcon from '@coreui/icons-react';
import { Logger, reloadPage } from '../../Utils/Utils';
import { requestHeaderPOSTWithAuth, requestHeaderGETWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

import Select from 'react-select';

const FILE_NAME = "CreateSubProgram.js";

class CreateSubProgram extends Component {

    constructor(props) {
        super(props);
        this.state = {
            name: '',
            description: '',
            programId: '',
            programs: [],
            programsLoadError: false,
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
        };
    }

    componentDidMount() {
        document.title = "Create Sub-Program";
        this.fetchPrograms();
    }

    fetchPrograms() {
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/program/list';
        const reqData = { page: 1, size: 100 };

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            if (result && result.data) {
                this.setState({ programs: result.data.content || [], programsLoadError: false });
            }
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchPrograms", "ERROR", "error", error);
            this.setState({ programsLoadError: true });
        });
    }

    handleSubmit = (e) => {
        e.preventDefault();
        const { name, description, programId } = this.state;
        const payload = { name, description: description || null, programId: Number(programId) };

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/sub-program';

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(payload), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ loadingModalVisible: false, failureModalVisible: true });
                setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "handleSubmit", "SUCCESS", "result", result);
            this.setState({ loadingModalState: 1 });
            setTimeout(() => this.resetForm(), 500);
        })
        .catch(error => {
            Logger(FILE_NAME, "handleSubmit", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    resetForm = () => {
        this.setState({ name: '', description: '', programId: '', loadingModalVisible: false, loadingModalState: 0, failureModalVisible: false });
    }

    render() {
        const { name, description, programId, programs, programsLoadError } = this.state;

        return (
            <div>
                <a href="#/sub-programs" style={{ textDecoration: 'none' }}>
                    <CButton color="secondary" className="mb-3">← Back to Sub-Programs</CButton>
                </a>

                {programsLoadError && (
                    <div style={{ padding: '12px 16px', marginBottom: '16px', backgroundColor: '#f8d7da', border: '1px solid #f5c6cb', borderRadius: '4px', color: '#721c24' }}>
                        ⚠️ Failed to load programs list. Please check your connection and <CButton color="link" style={{ padding: 0, color: '#721c24', textDecoration: 'underline' }} onClick={() => this.fetchPrograms()}>retry</CButton>.
                    </div>
                )}
                <CContainer>
                    <CRow className="justify-content-center">
                        <CCol md="6">
                            <CCardGroup>
                                <CCard className="p-4">
                                    <CCardBody>
                                        <CForm onSubmit={this.handleSubmit}>
                                            <h1>Create Sub-Program</h1>
                                            <br />

                                            <label><strong>Program *</strong></label>
                                            <div className="mb-3">
                                                <Select
                                                    value={programs.map(p => ({ value: String(p.id), label: `${p.name} (${p.type})` })).find(o => o.value === programId) || null}
                                                    onChange={(choice) => this.setState({ programId: choice ? choice.value : '' })}
                                                    options={programs.map(p => ({ value: String(p.id), label: `${p.name} (${p.type})` }))}
                                                    isClearable={true}
                                                    placeholder="Search program..."
                                                    styles={{ control: (base) => ({ ...base, minHeight: '38px' }) }}
                                                />
                                            </div>

                                            <label><strong>Name *</strong></label>
                                            <CInputGroup className="mb-3">
                                                <CInputGroupPrepend>
                                                    <CInputGroupText><CIcon name="cilPencil" /></CInputGroupText>
                                                </CInputGroupPrepend>
                                                <CInput
                                                    placeholder="Sub-program name"
                                                    type="text"
                                                    value={name}
                                                    onChange={(e) => this.setState({ name: e.target.value })}
                                                    required
                                                />
                                            </CInputGroup>

                                            <label><strong>Description</strong></label>
                                            <CInputGroup className="mb-3">
                                                <CInputGroupPrepend>
                                                    <CInputGroupText>📝</CInputGroupText>
                                                </CInputGroupPrepend>
                                                <textarea
                                                    placeholder="Description (optional)"
                                                    value={description}
                                                    onChange={(e) => this.setState({ description: e.target.value })}
                                                    rows="3"
                                                    style={{ flex: 1, padding: '6px 12px', border: '1px solid #d8dbe0', borderRadius: '0 4px 4px 0', resize: 'vertical' }}
                                                />
                                            </CInputGroup>

                                            <hr />
                                            <CRow>
                                                <CCol xs="6">
                                                    <CButton color="success" className="px-4" type="submit">CREATE</CButton>
                                                </CCol>
                                                <CCol xs="6" className="text-right">
                                                    <CButton color="danger" className="px-4" onClick={this.resetForm}>Reset</CButton>
                                                </CCol>
                                            </CRow>
                                        </CForm>
                                    </CCardBody>
                                </CCard>
                            </CCardGroup>
                        </CCol>
                    </CRow>
                </CContainer>
                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }
}

export default CreateSubProgram;
